namespace PixelForge {
public sealed partial class CutsceneEditor {
    public void AddAmbient(AmbientProject p,List<Frame> frames){
        if(exporting)throw new Exception("Дождитесь завершения экспорта катсцены.");p.Validate();if(frames.Count<2||frames.Count>240||scene.Layers.Count>=64)throw new Exception("Слишком много кадров или слоёв.");long pixels=scene.Layers.Sum(l=>l.Frames.Sum(f=>(long)f.W*f.H))+frames.Sum(f=>(long)f.W*f.H);if(pixels>64000000)throw new Exception("Лимит ресурсов катсцены — 64 млн пикселей.");
        Stop();EndLiveEdit();Remember();if(scene.Layers.Count==0){scene.Width=p.Width;scene.Height=p.Height;scene.OutputWidth=p.OutputWidth;scene.OutputHeight=p.OutputHeight;scene.Fps=p.Fps;scene.Duration=frames.Count/(double)p.Fps;scene.Crossfade=0;scene.Seamless=true;scene.Background=p.Background;}
        double scale=Math.Min(scene.Width/(double)p.Width,scene.Height/(double)p.Height);var layer=new SceneLayer {Name=p.Name,Frames=frames.Select(f=>f.Clone()).ToList(),Duration=scene.Duration,Fps=p.Fps,Loop=true,Scale=scale,EndScale=scale,LabelColor="#2E967D",ProceduralLoop=true,BackgroundLibraryId=p.LibraryId};layer.X=layer.EndX=(scene.Width-p.Width*scale)/2;layer.Y=layer.EndY=(scene.Height-p.Height*scale)/2;scene.Layers.Insert(0,layer);selected=layer;time=0;ShowProject();ShowLayer();RefreshLayers();RefreshView();view.SetZoom(0);Tell("Фон добавлен нижним слоем. Его собственный цикл: "+(frames.Count/(double)p.Fps).ToString("0.###")+" с.");
    }
    public void TestAmbientTransfer(AmbientProject p,List<Frame> frames){var previous=scene;var oldSelected=selected;scene=new Cutscene();selected=null;AddAmbient(p,frames);if(!scene.Layers[0].ProceduralLoop||scene.Width!=p.Width||scene.Height!=p.Height||scene.Crossfade!=0||!scene.Seamless||Math.Abs(scene.Duration-frames.Count/(double)p.Fps)>.00001)throw new Exception("Ambient transfer did not set exact loop");var old=scene.Layers[0];scene.Layers.Add(new SceneLayer {Name="Персонаж",Duration=scene.Duration,Frames=new List<Frame>{frames[0]}});AddAmbient(p,frames);if(scene.Layers[0]==old||scene.Layers[2].Name!="Персонаж")throw new Exception("Ambient layer not inserted behind existing layers");scene=previous;selected=oldSelected;history.Clear();dirty=false;ShowProject();ShowLayer();RefreshLayers();RefreshView();}
}
public sealed partial class MainWindow {
    public async Task AmbientSmoke(string dir){try{mainTabs.SelectedIndex=2;await Task.Delay(100);await backgrounds.SelfTest(dir);changed=false;Application.Current.Shutdown(0);}catch(Exception ex){Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"ambient-error.txt"),ex.ToString());changed=false;Application.Current.Shutdown(1);}}
}
public sealed partial class AmbientBackgroundEditor {
    public Action<AmbientProject,List<Frame>> TestTransfer;
    public async Task SelfTest(string dir){
        Directory.CreateDirectory(dir);var p=DemoProject();p.Duration=2;p.Fps=12;p.OutputWidth=640;p.OutputHeight=360;p.Base=AmbientEngine.Pixelize(p,CancellationToken.None);p.Validate();var photoBefore=(byte[])p.Photo.Data.Clone();
        if(!AmbientEngine.Render(p,0).Data.SequenceEqual(AmbientEngine.Render(p,p.Duration).Data)||!AmbientEngine.Render(p,.37).Data.SequenceEqual(AmbientEngine.Render(p,.37+p.Duration).Data))throw new Exception("Exact analytical loop failed");
        var frames=AmbientEngine.Frames(p,CancellationToken.None);if(frames.Count!=24||frames.All(f=>f.Data.SequenceEqual(frames[0].Data)))throw new Exception("Generated animation static or wrong length");
        foreach(int effect in new[]{0,1}){var single=AmbientEngine.Clone(p);single.Regions=single.Regions.Where(r=>r.Effect==effect).ToList();if(AmbientEngine.Render(single,0).Data.SequenceEqual(AmbientEngine.Render(single,p.Duration/4).Data))throw new Exception("An individual motion effect is static: "+effect);}
        var union=new bool[p.Width*p.Height];foreach(var r in p.Regions)for(int n=0;n<union.Length;n++)union[n]|=r.Mask[n];foreach(var frame in frames)for(int n=0;n<union.Length;n++)if(!union[n])for(int c=0;c<4;c++)if(frame.Data[n*4+c]!=p.Base.Data[n*4+c])throw new Exception("An unselected pixel moved or changed color");
        if(!p.Photo.Data.SequenceEqual(photoBefore))throw new Exception("Photo mutated");var still=AmbientEngine.Clone(p);still.Regions.Clear();if(!AmbientEngine.Render(still,.5).Data.SequenceEqual(p.Base.Data))throw new Exception("No-mask frame differs from static base");
        foreach(var r in still.Regions)r.Amplitude=0;var zero=AmbientEngine.Clone(p);foreach(var r in zero.Regions)r.Amplitude=0;if(!AmbientEngine.Render(zero,.53).Data.SequenceEqual(zero.Base.Data))throw new Exception("Zero motion changes image");
        var light=new AmbientRegion {Name="Свет",Effect=2,Lightness=5,Mask=new bool[p.Width*p.Height]};for(int y=30;y<50;y++)for(int x=210;x<240;x++)light.Mask[y*p.Width+x]=true;p.Regions.Add(light);if(!AmbientEngine.Render(p,0).Data.SequenceEqual(AmbientEngine.Render(p,2).Data))throw new Exception("Light loop seam failed");
        AmbientFile.Save(p,Path.Combine(dir,"lake.bgscene"));var loaded=AmbientFile.Load(Path.Combine(dir,"lake.bgscene"));if(!AmbientEngine.Render(loaded,.71).Data.SequenceEqual(AmbientEngine.Render(p,.71).Data))throw new Exception("Project photo/mask/region round-trip failed");
        var resized=AmbientEngine.Clone(p);resized.Width=160;resized.Height=90;AmbientEngine.ResizeMasks(resized,p.Width,p.Height);resized.Base=AmbientEngine.Pixelize(resized,CancellationToken.None);resized.Validate();if(resized.Regions.Any(r=>r.Mask.Length!=160*90))throw new Exception("Mask resize failed");
        var geometry=new AmbientProject {Width=32,Height=32,OutputWidth=320,OutputHeight=320,Duration=1,Photo=new Frame(32,16),Colors=16,Cover=false};for(int i=0;i<geometry.Photo.Data.Length;i+=4){geometry.Photo.Data[i+2]=255;geometry.Photo.Data[i+3]=255;}var fit=AmbientEngine.Pixelize(geometry,CancellationToken.None);if(fit.Data[3]!=255||fit.Data[(16*32+16)*4+2]!=255||fit.Data[2]==255)throw new Exception("Proportional photo fit failed");
        var finalFrames=AmbientEngine.Frames(p,CancellationToken.None);var scene=AmbientEngine.ToScene(p,finalFrames);await SceneExport.Encode(scene,Path.Combine(dir,"lake.mp4"),false,(i,n)=>{},CancellationToken.None);await SceneExport.Encode(scene,Path.Combine(dir,"lake.gif"),true,(i,n)=>{},CancellationToken.None);var gif=new GifBitmapDecoder(new Uri(Path.Combine(dir,"lake.gif")),BitmapCreateOptions.PreservePixelFormat,BitmapCacheOption.OnLoad);if(gif.Frames.Count!=24||!System.Text.Encoding.ASCII.GetString(File.ReadAllBytes(Path.Combine(dir,"lake.gif"))).Contains("NETSCAPE2.0"))throw new Exception("Infinite-loop GIF metadata/frame count failed");if(TestTransfer!=null)TestTransfer(p,finalFrames);
        string decoded=Path.Combine(dir,"gif-decoded.rgba");await SceneExport.Run("-hide_banner -loglevel error -y -i \""+Path.Combine(dir,"lake.gif")+"\" -pix_fmt rgba -f rawvideo \""+decoded+"\"",CancellationToken.None);var gifData=File.ReadAllBytes(decoded);int frameBytes=640*360*4;if(gifData.Length!=frameBytes*24)throw new Exception("GIF decoded length mismatch");var animatedMask=new bool[p.Width*p.Height];foreach(var r in p.Regions)for(int n=0;n<animatedMask.Length;n++)animatedMask[n]|=r.Mask[n];for(int f=1;f<24;f++)for(int y=0;y<360;y++)for(int x=0;x<640;x++){if(animatedMask[(y/2)*p.Width+x/2])continue;int pixel=(y*640+x)*4;for(int c=0;c<4;c++)if(gifData[f*frameBytes+pixel+c]!=gifData[pixel+c])throw new Exception("Exported GIF made a static pixel flicker");}
        project=AmbientEngine.Clone(p);selected=project.Regions[0];Sync();ChangeRegion(r=>r.Amplitude=2);regions.SelectedIndex=1;int spot=project.Width+1;bool prior=project.Regions[1].Mask[spot];canvas.BeforeStroke();canvas.Paint(1,1,prior);canvas.StrokeFinished();if(project.Regions[1].Mask[spot]==prior)throw new Exception("Brush after parameter edit changed a stale region");Undo();if(project.Regions[1].Mask[spot]!=prior)throw new Exception("Brush undo failed");AddRegion();int beforeEmptyEdit=history.Count;ChangeRegion(r=>r.Effect=1);if(selected.Effect!=1||history.Count!=beforeEmptyEdit+1)throw new Exception("Empty region editing failed");beforeEmptyEdit=history.Count;ChangeRegion(r=>r.Effect=1);if(history.Count!=beforeEmptyEdit)throw new Exception("Region render caches polluted undo/equality");
        project=p;selected=p.Regions[0];currentFrame=0;dirty=false;Sync();canvas.Fit();side.SelectedIndex=1;showMask.IsChecked=false;canvas.ShowMask=false;Preview();var host=Window.GetWindow(this);host.Width=1380;host.Height=900;host.UpdateLayout();await Task.Delay(100);var shot=new RenderTargetBitmap((int)host.ActualWidth,(int)host.ActualHeight,96,96,PixelFormats.Pbgra32);shot.Render(host);Frame.From(shot).Save(Path.Combine(dir,"ambient-editor.png"));host.Width=720;host.Height=800;host.UpdateLayout();await Task.Delay(100);if(canvas.ActualWidth<100||canvas.ActualHeight<80)throw new Exception("Narrow background layout unusable");shot=new RenderTargetBitmap((int)host.ActualWidth,(int)host.ActualHeight,96,96,PixelFormats.Pbgra32);shot.Render(host);Frame.From(shot).Save(Path.Combine(dir,"ambient-narrow.png"));
        File.WriteAllText(Path.Combine(dir,"ambient-checks.txt"),"PASS: exact periodic endpoints; deterministic motion; water and grass each animate independently; generated frame count; every unmasked RGBA byte unchanged in every frame; original photo unchanged; empty mask and zero amplitude; periodic light; self-contained photo/base/mask round-trip; mask resize; proportional fit; MP4 encode; infinite GIF decode and metadata; every static pixel remains constant in decoded GIF; brush after parameter editing/region selection; mask stroke undo; transfer as back layer with exact scene period; 1380/720 layouts.\r\n");dirty=false;
    }
}
